/**
 * `agent/agent.ts`: model, runtime architecture, working directory, hosting, and concurrency.
 */
import { basename, isAbsolute, join, resolve } from "node:path";
import { isRecord } from "../is-record.js";
import { MAX_RUNNING_TURNS_LIMIT, } from "../../types.js";
import { normalizePositiveInt } from "../bounded-int.js";
import { hostingEntryErrors, MAX_EGRESS_DOMAINS, validateContainerImageName } from "../hosting.js";
import { defaultLocalHarnessCwd, isNestedInGitRepo } from "../workspace.js";
import { displayPath, isBlank, pushConfigDiagnostic } from "./context.js";
import { findModuleFile } from "./fs.js";
import { importDefault } from "./modules.js";
/** Author-facing default when {@link AgentConfig.architecture} is omitted. */
export const DEFAULT_AGENT_ARCHITECTURE = "v2";
export function resolveArchitecture(ctx, agentDir, architecture) {
    if (architecture === undefined) {
        return DEFAULT_AGENT_ARCHITECTURE;
    }
    if (architecture === "v1" || architecture === "v2") {
        return architecture;
    }
    pushConfigDiagnostic(ctx, {
        severity: "error",
        path: displayPath(ctx, join(agentDir, "agent.ts")),
        message: `architecture must be "v1" or "v2"; got ${JSON.stringify(architecture)}.`,
    });
    return undefined;
}
export function rejectPersistentOption(ctx, agentDir, config) {
    if (!isRecord(config) || !Object.hasOwn(config, "persistent")) {
        return;
    }
    pushConfigDiagnostic(ctx, {
        severity: "error",
        path: displayPath(ctx, join(agentDir, "agent.ts")),
        message: "persistent was removed. Delete it from defineAgent.",
    });
}
/** Absolute harness cwd parent, or undefined when unset / blank. */
export function resolveAgentCwd(ctx, authored) {
    if (authored === undefined) {
        return undefined;
    }
    const trimmed = authored.trim();
    if (trimmed === "") {
        return undefined;
    }
    return isAbsolute(trimmed) ? trimmed : resolve(ctx.rootDir, trimmed);
}
/**
 * Nested git checkouts inherit ancestor AGENTS.md / .cursor rules and MCP.
 * Point those harnesses at ~/.cache/agent-serve/<dir> unless the agent
 * already set cwd or workspaceDir.
 */
export async function resolveLocalCwd(ctx, authoredCwd, authoredWorkspaceDir) {
    const cwd = resolveAgentCwd(ctx, authoredCwd);
    if (cwd !== undefined) {
        return cwd;
    }
    if (resolveAgentCwd(ctx, authoredWorkspaceDir) !== undefined) {
        return undefined;
    }
    if (!(await isNestedInGitRepo(ctx.rootDir))) {
        return undefined;
    }
    return defaultLocalHarnessCwd(basename(ctx.rootDir));
}
/**
 * Validate the authored `hosting` block against the same grammar the
 * backend enforces on deploy, then union it with what mounted extensions
 * declare (authored entries first; mounts are checked where they mount).
 * Violations are warning diagnostics (reported by `agent-sdk validate`), not
 * hard failures: the backend stays authoritative.
 */
export function resolveHosting(ctx, agentDir, hosting, extensions) {
    const agentPath = displayPath(ctx, join(agentDir, "agent.ts"));
    const warn = (message) => {
        pushConfigDiagnostic(ctx, { severity: "warning", path: agentPath, message });
    };
    for (const error of hostingEntryErrors(hosting ?? {})) {
        warn(`hosting.${error}`);
    }
    if (hosting?.image !== undefined) {
        const imageError = validateContainerImageName(hosting.image);
        if (imageError !== undefined) {
            warn(`hosting.image: ${imageError}`);
        }
    }
    const mountedEgress = extensions.flatMap((extension) => extension.hosting?.egressDomains ?? []);
    const egressDomains = [...new Set([...(hosting?.egressDomains ?? []), ...mountedEgress])];
    if (egressDomains.length > MAX_EGRESS_DOMAINS) {
        const withMounts = mountedEgress.length > 0 ? " with mounted extensions" : "";
        warn(`hosting.egressDomains lists ${egressDomains.length} domains${withMounts}; deploys are capped at ${MAX_EGRESS_DOMAINS}.`);
    }
    const secretNames = [
        ...new Set([
            ...(hosting?.secretNames ?? []),
            ...extensions.flatMap((extension) => extension.hosting?.secretNames ?? []),
        ]),
    ];
    if (egressDomains.length === 0 && secretNames.length === 0 && hosting?.image === undefined) {
        return undefined;
    }
    return {
        egressDomains: egressDomains.length === 0 ? undefined : egressDomains,
        secretNames: secretNames.length === 0 ? undefined : secretNames,
        image: hosting?.image,
    };
}
/**
 * Validate the authored `concurrency` block. Invalid values are **error**
 * diagnostics (serve refuses to start): silently dropping a turn ceiling
 * would fail open to unlimited parallelism, the opposite of what the
 * author asked for.
 */
export function resolveConcurrency(ctx, agentDir, concurrency) {
    if (concurrency === undefined || concurrency.maxRunningTurns === undefined) {
        return undefined;
    }
    try {
        return {
            maxRunningTurns: normalizePositiveInt(concurrency.maxRunningTurns, {
                label: "concurrency.maxRunningTurns",
                max: MAX_RUNNING_TURNS_LIMIT,
            }),
        };
    }
    catch (error) {
        pushConfigDiagnostic(ctx, {
            severity: "error",
            path: displayPath(ctx, join(agentDir, "agent.ts")),
            message: error instanceof Error ? error.message : String(error),
        });
        return undefined;
    }
}
export async function loadAgentConfig(ctx, agentDir, isRoot) {
    const configPath = await findModuleFile(agentDir, "agent");
    if (configPath === undefined) {
        pushConfigDiagnostic(ctx, {
            severity: "error",
            path: displayPath(ctx, join(agentDir, "agent.ts")),
            message: isRoot
                ? "agent.ts is required on the root agent: default-export defineAgent({ ... })"
                : "agent.ts is required on a subagent: default-export defineAgent({ description: ... })",
        });
        return undefined;
    }
    const definition = await importDefault(ctx, configPath, "agent");
    if (definition === undefined) {
        return undefined;
    }
    // oxlint-disable-next-line typescript/no-unsafe-type-assertion -- the loader already checked this definition brand; importDefault returns unknown
    const config = definition;
    if (!isRoot && isBlank(config.description)) {
        pushConfigDiagnostic(ctx, {
            severity: "error",
            path: displayPath(ctx, configPath),
            message: "Subagents require a description; the parent model reads it to decide when to delegate.",
        });
    }
    return config;
}
export function isValidModelSetting(model) {
    if (typeof model === "string") {
        return model.trim() !== "";
    }
    return isRecord(model) && typeof model.id === "string" && model.id.trim() !== "";
}
/**
 * Authored `fallbacks` on `defineAgent`. `undefined` when the field is
 * omitted. An invalid entry is a discovery error and drops the list: a
 * half-applied chain would retry onto a model the author did not name.
 */
export function resolveModelFallbacks(ctx, configPath, fallbacks) {
    if (fallbacks === undefined) {
        return undefined;
    }
    if (!Array.isArray(fallbacks) || !fallbacks.every(isValidModelSetting)) {
        pushConfigDiagnostic(ctx, {
            severity: "error",
            path: displayPath(ctx, configPath),
            message: "fallbacks must be an array of model ids or { id, params } selections, the same shape as model.",
        });
        return undefined;
    }
    return fallbacks.length > 0 ? fallbacks : undefined;
}
/**
 * Authored `fallbackAfterStream` on `defineAgent`. A non-boolean is a
 * discovery error and leaves the default, which never restarts a turn that
 * has already streamed.
 */
export function resolveFallbackAfterStream(ctx, configPath, fallbackAfterStream) {
    if (fallbackAfterStream === undefined) {
        return undefined;
    }
    if (typeof fallbackAfterStream !== "boolean") {
        pushConfigDiagnostic(ctx, {
            severity: "error",
            path: displayPath(ctx, configPath),
            message: "fallbackAfterStream must be a boolean.",
        });
        return undefined;
    }
    return fallbackAfterStream;
}
